CREATE TABLE fb_upload_task (
 id CHAR(36) PRIMARY KEY, tenant_id VARCHAR(128) NOT NULL, owner_id VARCHAR(128) NOT NULL, storage_id VARCHAR(100) NOT NULL, object_key VARCHAR(1024) NOT NULL, original_name VARCHAR(512) NOT NULL, business_type VARCHAR(128), business_id VARCHAR(256), content_type VARCHAR(255), expected_size BIGINT NOT NULL, claimed_sha256 CHAR(64), part_size BIGINT NOT NULL, total_parts INT NOT NULL, status VARCHAR(32) NOT NULL, provider_upload_id VARCHAR(1024), result_file_id CHAR(36), expires_at DATETIME(6) NOT NULL, lease_owner VARCHAR(200), lease_until DATETIME(6), version BIGINT NOT NULL DEFAULT 0, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, KEY idx_fb_upload_actor(tenant_id,owner_id,status), KEY idx_fb_upload_expiry(status,expires_at), KEY idx_fb_upload_lease(status,lease_until), CONSTRAINT fk_fb_upload_result FOREIGN KEY(result_file_id) REFERENCES fb_file_reference(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE fb_upload_part (
 id CHAR(36) PRIMARY KEY, upload_id CHAR(36) NOT NULL, part_number INT NOT NULL, size_bytes BIGINT NOT NULL, sha256 CHAR(64) NOT NULL, provider_part_tag VARCHAR(1024), status VARCHAR(32) NOT NULL, created_at DATETIME(6) NOT NULL, updated_at DATETIME(6) NOT NULL, CONSTRAINT fk_fb_part_upload FOREIGN KEY(upload_id) REFERENCES fb_upload_task(id), UNIQUE KEY uk_fb_upload_part(upload_id,part_number), KEY idx_fb_part_status(upload_id,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
